challenges.reference:
import java.util.*;

class Solution {
    static int[] twoSum(int[] nums, int alvo) {
        Map<Integer, Integer> mapa = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int falta = alvo - nums[i];
            if (mapa.containsKey(falta)) return new int[]{mapa.get(falta), i};
            mapa.put(nums[i], i);
        }
        return new int[]{-1, -1};
    }
}

