challenges.reference:
class Solution {
    static int[] rotacionar(int[] nums, int k) {
        int n = nums.length;
        if (n == 0) return nums;
        k %= n;
        int[] r = new int[n];
        for (int i = 0; i < n; i++) r[(i + k) % n] = nums[i];
        return r;
    }
}

