class Solution {
    static int segundoMaior(int[] nums) {
        long max1 = Long.MIN_VALUE, max2 = Long.MIN_VALUE;
        for (int x : nums) {
            if (x > max1) { max2 = max1; max1 = x; }
            else if (x < max1 && x > max2) { max2 = x; }
        }
        return (int) max2;
    }
}

