challenges.reference:
class Solution {
    static int maxDiferenca(int[] nums) {
        int m = 0;
        for (int i = 1; i < nums.length; i++)
            m = Math.max(m, Math.abs(nums[i] - nums[i - 1]));
        return m;
    }
}

